[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

        :root {
            --primary: #3861FB;
            --text-dark: #0D1421;
            --text-secondary: #808A9D;
            --positive: #16c784;
            --negative: #ea3943;
            --bg: #ffffff;
            --bg-secondary: #f3f5f7;
            --border: #e2e5ea;
            --hover: #f8f9fa;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--bg);
            color: var(--text-dark);
            line-height: 1.5;
            -webkit-font-smoothing: antialiased;
        }

        /* Navigation */
        .nav {
            background: var(--text-dark);
            padding: 0 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 56px;
        }

        .nav-brand {
            display: flex;
            align-items: center;
            gap: 8px;
            color: #fff;
            font-weight: 700;
            font-size: 18px;
        }

        .nav-brand i { color: var(--primary); }

        .nav-links {
            display: flex;
            gap: 32px;
            list-style: none;
        }

        .nav-links a {
            color: rgba(255,255,255,0.7);
            text-decoration: none;
            font-size: 13px;
            font-weight: 500;
            transition: color 0.2s;
        }

        .nav-links a:hover { color: #fff; }

        .nav-actions { display: flex; gap: 12px; }

        .btn {
            padding: 8px 16px;
            border-radius: 6px;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            border: none;
            transition: all 0.2s;
        }

        .btn-outline {
            background: transparent;
            color: rgba(255,255,255,0.7);
            border: 1px solid rgba(255,255,255,0.2);
        }

        .btn-outline:hover { background: rgba(255,255,255,0.1); color: #fff; }

        .btn-primary {
            background: var(--primary);
            color: #fff;
        }

        .btn-primary:hover { background: #2d4fe0; }

        /* Top Bar Metrics */
        .top-bar {
            background: var(--bg-secondary);
            border-bottom: 1px solid var(--border);
            padding: 12px 24px;
            display: flex;
            gap: 32px;
            flex-wrap: wrap;
        }

        .metric {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .metric-label {
            font-size: 11px;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            font-weight: 500;
        }

        .metric-value {
            font-size: 16px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .metric-value .change { font-size: 12px; font-weight: 500; }
        .metric-value .positive { color: var(--positive); }
        .metric-value .negative { color: var(--negative); }

        .fear-greed {
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .fear-greed-badge {
            background: var(--positive);
            color: #fff;
            font-size: 11px;
            padding: 2px 8px;
            border-radius: 4px;
            font-weight: 600;
        }

        /* Promotional Banner */
        .promo-banner {
            background: linear-gradient(135deg, var(--primary), #5a7df4);
            padding: 10px 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 16px;
            color: #fff;
            font-size: 13px;
            position: relative;
            overflow: hidden;
        }

        .promo-slide {
            display: none;
            animation: fadeIn 0.3s ease;
        }

        .promo-slide.active { display: block; }

        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

        .promo-dots {
            display: flex;
            gap: 6px;
        }

        .promo-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: rgba(255,255,255,0.4);
            cursor: pointer;
        }

        .promo-dot.active { background: #fff; }

        /* AI Alerts Bar */
        .ai-alerts {
            background: #fff;
            border-bottom: 1px solid var(--border);
            padding: 12px 24px;
            display: flex;
            align-items: center;
            gap: 16px;
            flex-wrap: wrap;
        }

        .ai-badge {
            background: linear-gradient(135deg, #9333ea, #a855f7);
            color: #fff;
            font-size: 11px;
            padding: 4px 10px;
            border-radius: 4px;
            font-weight: 600;
            white-space: nowrap;
        }

        .ai-topic {
            font-size: 13px;
            color: var(--text-dark);
            flex: 1;
            min-width: 200px;
        }

        .ai-suggestions {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }

        .ai-suggestion {
            font-size: 12px;
            color: var(--primary);
            background: rgba(56,97,251,0.08);
            padding: 4px 10px;
            border-radius: 4px;
            cursor: pointer;
            white-space: nowrap;
            transition: background 0.2s;
        }

        .ai-suggestion:hover { background: rgba(56,97,251,0.15); }

        /* Filters Bar */
        .filters-bar {
            padding: 16px 24px;
            border-bottom: 1px solid var(--border);
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .tabs {
            display: flex;
            gap: 4px;
            overflow-x: auto;
            padding-bottom: 2px;
        }

        .tab {
            padding: 8px 16px;
            font-size: 13px;
            font-weight: 500;
            color: var(--text-secondary);
            background: none;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            white-space: nowrap;
            transition: all 0.2s;
        }

        .tab:hover { background: var(--hover); color: var(--text-dark); }

        .tab.active {
            background: var(--text-dark);
            color: #fff;
        }

        .network-tabs {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }

        .network-tab {
            font-size: 12px;
            padding: 6px 12px;
            color: var(--text-secondary);
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 20px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .network-tab:hover { border-color: var(--primary); color: var(--primary); }

        .network-tab.active {
            background: var(--primary);
            border-color: var(--primary);
            color: #fff;
        }

        /* Table Controls */
        .table-controls {
            padding: 16px 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            flex-wrap: wrap;
        }

        .control-left { display: flex; gap: 8px; }

        .control-btn {
            padding: 8px 12px;
            font-size: 12px;
            font-weight: 500;
            color: var(--text-secondary);
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 6px;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s;
        }

        .control-btn:hover { border-color: var(--primary); color: var(--primary); }

        .sort-select {
            padding: 8px 12px;
            font-size: 12px;
            font-weight: 500;
            color: var(--text-secondary);
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 6px;
            cursor: pointer;
        }

        .control-right { display: flex; gap: 8px; align-items: center; }

        .page-info {
            font-size: 12px;
            color: var(--text-secondary);
            white-space: nowrap;
        }

        /* Index Row */
        .index-row {
            background: rgba(56,97,251,0.04);
            border: 1px solid rgba(56,97,251,0.15);
            margin: 0 24px;
            padding: 12px 16px;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 12px;
        }

        .index-name {
            font-weight: 600;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .index-tag {
            background: var(--primary);
            color: #fff;
            font-size: 10px;
            padding: 2px 6px;
            border-radius: 3px;
        }

        .index-values {
            display: flex;
            gap: 24px;
            font-size: 12px;
        }

        .index-stat {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 2px;
        }

        .index-stat-label { color: var(--text-secondary); font-size: 10px; }
        .index-stat-value { font-weight: 600; }

        /* Rankings Table */
        .table-container {
            padding: 0 24px 24px;
            overflow-x: auto;
        }

        .rankings-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 13px;
        }

        .rankings-table th {
            text-align: left;
            padding: 12px 8px;
            font-size: 11px;
            font-weight: 500;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            border-bottom: 2px solid var(--border);
            white-space: nowrap;
        }

        .rankings-table th.right { text-align: right; }

        .rankings-table td {
            padding: 12px 8px;
            border-bottom: 1px solid var(--border);
            white-space: nowrap;
        }

        .rankings-table td.right { text-align: right; }

        .rankings-table tr:hover td { background: var(--hover); }

        .rankings-table .name-cell {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .rankings-table .rank { color: var(--text-secondary); font-weight: 500; width: 28px; }

        .coin-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            background: var(--bg-secondary);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: 600;
            color: var(--text-secondary);
        }

        .coin-name { font-weight: 500; }
        .coin-symbol { color: var(--text-secondary); font-size: 11px; }

        .price { font-weight: 500; font-variant-numeric: tabular-nums; }

        .change { font-weight: 500; }
        .change.p { color: var(--positive); }
        .change.n { color: var(--negative); }

        .market-cap, .volume { font-variant-numeric: tabular-nums; color: var(--text-secondary); font-size: 12px; }

        .supply { font-variant-numeric: tabular-nums; color: var(--text-secondary); font-size: 12px; }

        .sparkline {
            display: flex;
            align-items: flex-end;
            gap: 1px;
            height: 28px;
        }

        .spark-bar {
            width: 4px;
            background: var(--primary);
            border-radius: 1px;
            opacity: 0.6;
        }

        .spark-bar:last-child { opacity: 1; }

        /* Pagination */
        .pagination {
            padding: 16px 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 4px;
            flex-wrap: wrap;
        }

        .page-btn {
            min-width: 36px;
            height: 36px;
            padding: 0 12px;
            font-size: 13px;
            color: var(--text-secondary);
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .page-btn:hover { border-color: var(--primary); color: var(--primary); }

        .page-btn.active {
            background: var(--primary);
            border-color: var(--primary);
            color: #fff;
        }

        .page-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        /* Market Summary */
        .market-summary {
            padding: 24px;
            background: var(--bg-secondary);
            margin: 0 24px 24px;
            border-radius: 8px;
        }

        .summary-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
        }

        .summary-title {
            font-size: 14px;
            font-weight: 600;
        }

        .read-more {
            font-size: 13px;
            color: var(--primary);
            cursor: pointer;
            background: none;
            border: none;
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .read-more i { transition: transform 0.2s; }

        .read-more.expanded i { transform: rotate(180deg); }

        .summary-content {
            font-size: 13px;
            line-height: 1.7;
            color: var(--text-secondary);
        }

        .summary-content strong { color: var(--text-dark); }

        .summary-extra {
            display: none;
            margin-top: 12px;
            padding-top: 12px;
            border-top: 1px solid var(--border);
        }

        .summary-extra.show { display: block; }

        .summary-stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 12px;
        }

        .summary-stat {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .summary-stat-label { font-size: 11px; color: var(--text-secondary); }
        .summary-stat-value { font-size: 14px; font-weight: 600; }

        /* Info Content */
        .info-content {
            padding: 24px;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
        }

        .info-card h3 {
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 8px;
        }

        .info-card p {
            font-size: 13px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        /* Footer */
        .footer {
            background: var(--text-dark);
            color: rgba(255,255,255,0.7);
            padding: 40px 24px 24px;
            margin-top: 24px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
            gap: 32px;
            margin-bottom: 32px;
        }

        .footer-col h4 {
            color: #fff;
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 12px;
        }

        .footer-col ul {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .footer-col a {
            color: rgba(255,255,255,0.6);
            text-decoration: none;
            font-size: 13px;
            transition: color 0.2s;
        }

        .footer-col a:hover { color: #fff; }

        .footer-bottom {
            padding-top: 24px;
            border-top: 1px solid rgba(255,255,255,0.1);
            text-align: center;
            font-size: 12px;
        }

        /* Dropdown Panels */
        .dropdown-panel {
            position: absolute;
            background: #fff;
            border: 1px solid var(--border);
            border-radius: 8px;
            box-shadow: 0 4px 20px rgba(0,0,0,0.12);
            z-index: 100;
            display: none;
            min-width: 200px;
        }

        .dropdown-panel.show { display: block; }

        .dropdown-section {
            padding: 12px;
            border-bottom: 1px solid var(--border);
        }

        .dropdown-section:last-child { border-bottom: none; }

        .dropdown-title {
            font-size: 11px;
            font-weight: 600;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 8px;
        }

        .checkbox-item {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 6px 0;
            font-size: 13px;
            cursor: pointer;
        }

        .checkbox-item input { cursor: pointer; }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-links { display: none; }
            .top-bar { gap: 16px; }
            .promo-banner { flex-direction: column; gap: 8px; }
            .ai-suggestions { display: none; }
            .table-controls { flex-direction: column; align-items: flex-start; }
            .index-row { margin: 0 12px; }
            .table-container { padding: 0 12px 12px; }
            .market-summary { margin: 0 12px 12px; }
        }

        /* Utilities */
        .text-positive { color: var(--positive); }
        .text-negative { color: var(--negative); }
        .font-medium { font-weight: 500; }
        .relative { position: relative; }
    </style>
</head>
<body>
    <!-- Navigation -->
    <nav class="nav">
        <div class="nav-brand">
            <i class="ri-money-dollar-circle-fill" style="font-size: 24px;"></i>
            CoinTracker Pro
        </div>
        <ul class="nav-links">
            <li><a href="#">Cryptocurrencies</a></li>
            <li><a href="#">Dashboards</a></li>
            <li><a href="#">Exchanges</a></li>
            <li><a href="#">DexScan</a></li>
            <li><a href="#">More</a></li>
        </ul>
        <div class="nav-actions">
            <button class="btn btn-outline">Log In</button>
            <button class="btn btn-primary">Sign Up</button>
        </div>
    </nav>

    <!-- Top Bar Metrics -->
    <div class="top-bar">
        <div class="metric">
            <span class="metric-label">Market Cap</span>
            <span class="metric-value">$2.56T <span class="change positive">↑ 1.46%</span></span>
        </div>
        <div class="metric">
            <span class="metric-label">CTP20 Index</span>
            <span class="metric-value">$155.36 <span class="change positive">↑ 1.5%</span></span>
        </div>
        <div class="metric">
            <span class="metric-label">Fear & Greed</span>
            <span class="metric-value fear-greed">
                57 <span class="fear-greed-badge">Neutral</span>
            </span>
        </div>
        <div class="metric">
            <span class="metric-label">Altcoin Season</span>
            <span class="metric-value">37/100 <span class="change" style="color: var(--negative);">Bitcoin season</span></span>
        </div>
    </div>

    <!-- Promotional Banner -->
    <div class="promo-banner">
        <div class="promo-slide active">📢 CTP Launch: Secure $GENIUS Airdrop — Join Now</div>
        <div class="promo-slide">🚀 Partner Promotion: Trade on Binance with 0 fees this weekend</div>
        <div class="promo-dots">
            <span class="promo-dot active" onclick="showSlide(0)"></span>
            <span class="promo-dot" onclick="showSlide(1)"></span>
        </div>
    </div>

    <!-- AI Alerts Bar -->
    <div class="ai-alerts">
        <span class="ai-badge">AI</span>
        <span class="ai-topic">Stablecoin issuer eyes Solana DeFi expansion 👀</span>
        <div class="ai-suggestions">
            <span class="ai-suggestion">Why is the market up today?</span>
            <span class="ai-suggestion">Are altcoins outperforming?</span>
            <span class="ai-suggestion">Trending narratives?</span>
            <span class="ai-suggestion">Bullish momentum?</span>
            <span class="ai-suggestion">Upcoming events?</span>
        </div>
    </div>

    <!-- Filters Bar -->
    <div class="filters-bar">
        <div class="tabs" id="categoryTabs">
            <button class="tab active" data-category="top">Top</button>
            <button class="tab" data-category="trending">Trending</button>
            <button class="tab" data-category="watchlist">Watchlist</button>
            <button class="tab" data-category="prediction">Prediction Markets</button>
            <button class="tab" data-category="visited">Most Visited</button>
            <button class="tab" data-category="new">New</button>
            <button class="tab" data-category="more">More ▾</button>
        </div>
        <div class="network-tabs" id="networkTabs">
            <button class="network-tab active" data-network="all">All Networks</button>
            <button class="network-tab" data-network="bsc">BSC</button>
            <button class="network-tab" data-network="solana">Solana</button>
            <button class="network-tab" data-network="base">Base</button>
            <button class="network-tab" data-network="ethereum">Ethereum</button>
            <button class="network-tab" data-network="more">More ▾</button>
        </div>
    </div>

    <!-- Table Controls -->
    <div class="table-controls">
        <div class="control-left">
            <div class="relative">
                <button class="control-btn" onclick="toggleDropdown('sortDropdown')">
                    <i class="ri-sort-desc"></i> Market Cap ▾
                </button>
                <div class="dropdown-panel" id="sortDropdown">
                    <div class="dropdown-section">
                        <div class="dropdown-title">Sort By</div>
                        <div class="checkbox-item"><input type="radio" name="sort" checked> Market Cap</div>
                        <div class="checkbox-item"><input type="radio" name="sort"> Volume (24h)</div>
                        <div class="checkbox-item"><input type="radio" name="sort"> Price</div>
                        <div class="checkbox-item"><input type="radio" name="sort"> Change (24h)</div>
                    </div>
                </div>
            </div>
            <div class="relative">
                <button class="control-btn" onclick="toggleDropdown('filterDropdown')">
                    <i class="ri-filter-line"></i> Filters
                </button>
                <div class="dropdown-panel" id="filterDropdown">
                    <div class="dropdown-section">
                        <div class="dropdown-title">Price Change</div>
                        <div class="checkbox-item"><input type="checkbox" checked> 1h %</div>
                        <div class="checkbox-item"><input type="checkbox" checked> 24h %</div>
                        <div class="checkbox-item"><input type="checkbox" checked> 7d %</div>
                    </div>
                    <div class="dropdown-section">
                        <div class="dropdown-title">Market Cap</div>
                        <div class="checkbox-item"><input type="checkbox" checked> All Sizes</div>
                        <div class="checkbox-item"><input type="checkbox"> > $1B</div>
                        <div class="checkbox-item"><input type="checkbox"> > $100M</div>
                    </div>
                </div>
            </div>
            <div class="relative">
                <button class="control-btn" onclick="toggleDropdown('columnDropdown')">
                    <i class="ri-table-line"></i> Columns
                </button>
                <div class="dropdown-panel" id="columnDropdown">
                    <div class="dropdown-section">
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('price')"> Price</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('1h')"> 1h %</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('24h')"> 24h %</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('7d')"> 7d %</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('mcap')"> Market Cap</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('vol')"> Volume(24h)</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('supply')"> Circulating Supply</div>
                        <div class="checkbox-item"><input type="checkbox" checked onclick="toggleColumn('spark')"> Last 7 Days</div>
                    </div>
                </div>
            </div>
