        // Format numbers
        function formatNum(num, decimals = 2) {
            if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
            if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
            if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
            if (num >= 1e3) return (num / 1e3).toFixed(2) + 'K';
            return num.toFixed(decimals);
        }

        function formatPrice(price) {
            if (price >= 1000) return '$' + price.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
            if (price >= 1) return '$' + price.toFixed(2);
            return '$' + price.toFixed(4);
        }

        function formatChange(change) {
            const cls = change >= 0 ? 'p' : 'n';
            const sign = change >= 0 ? '+' : '';
            return `<span class="change ${cls}">${sign}${change.toFixed(2)}%</span>`;
        }

        function renderSparkline(data) {
            const max = Math.max(...data);
            const min = Math.min(...data);
            const range = max - min || 1;
            return data.map(v => {
                const h = Math.max(4, Math.round(4 + ((v - min) / range) * 24));
                return `<div class="spark-bar" style="height:${h}px"></div>`;
            }).join('');
        }

        // Render table
        function renderTable(page = 1) {
            const tbody = document.getElementById('cryptoTableBody');
            const perPage = 100;
            const start = (page - 1) * perPage;
            const end = start + perPage;
            const pageData = cryptoData.slice(start, end);

            tbody.innerHTML = pageData.map(coin => `
                <tr>
                    <td>${coin.rank}</td>
                    <td>
                        <div class="name-cell">
                            <div class="coin-icon">${coin.symbol.slice(0,2)}</div>
                            <div>
                                <div class="coin-name">${coin.name}</div>
                                <div class="coin-symbol">${coin.symbol}</div>
                            </div>
                        </div>
                    </td>
                    <td class="right price-col">${formatPrice(coin.price)}</td>
                    <td class="right change-col">${formatChange(coin.change1h)}</td>
                    <td class="right change-col">${formatChange(coin.change24h)}</td>
                    <td class="right change-col">${formatChange(coin.change7d)}</td>
                    <td class="right mcap-col">$${formatNum(coin.mcap)}</td>
                    <td class="right vol-col">$${formatNum(coin.vol)}</td>
                    <td class="right supply-col">${coin.supply}</td>
                    <td class="spark-col"><div class="sparkline">${renderSparkline(coin.spark)}</div></td>
                </tr>
            `).join('');
        }

        // Render pagination
        function renderPagination(page = 1) {
            const totalPages = 84;
            const container = document.getElementById('pagination');
            let html = `<button class="page-btn" ${page === 1 ? 'disabled' : ''} onclick="goToPage(${page - 1})"><i class="ri-arrow-left-s-line"></i></button>`;

            for (let i = 1; i <= Math.min(totalPages, 10); i++) {
                html += `<button class="page-btn ${i === page ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
            }
            if (totalPages > 10) {
                html += `<span style="padding:0 8px;color:var(--text-secondary)">...</span>`;
                html += `<button class="page-btn" onclick="goToPage(${totalPages})">${totalPages}</button>`;
            }

            html += `<button class="page-btn" ${page === totalPages ? 'disabled' : ''} onclick="goToPage(${page + 1})"><i class="ri-arrow-right-s-line"></i></button>`;
            container.innerHTML = html;
        }

        function goToPage(page) {
            renderTable(page);
            renderPagination(page);
        }

        // Banner carousel
        let currentSlide = 0;
        function showSlide(idx) {
            const slides = document.querySelectorAll('.promo-slide');
            const dots = document.querySelectorAll('.promo-dot');
            slides[currentSlide].classList.remove('active');
            dots[currentSlide].classList.remove('active');
            currentSlide = idx;
            slides[currentSlide].classList.add('active');
            dots[currentSlide].classList.add('active');
        }

        setInterval(() => {
            showSlide((currentSlide + 1) % 2);
        }, 5000);

        // Tab switching
        document.querySelectorAll('#categoryTabs .tab').forEach(tab => {
            tab.addEventListener('click', function() {
                document.querySelectorAll('#categoryTabs .tab').forEach(t => t.classList.remove('active'));
                this.classList.add('active');
            });
        });

        document.querySelectorAll('#networkTabs .network-tab').forEach(tab => {
            tab.addEventListener('click', function() {
                document.querySelectorAll('#networkTabs .network-tab').forEach(t => t.classList.remove('active'));
                this.classList.add('active');
            });
        });

        // Dropdowns
        function toggleDropdown(id) {
            const panel = document.getElementById(id);
            const wasOpen = panel.classList.contains('show');
            document.querySelectorAll('.dropdown-panel').forEach(p => p.classList.remove('show'));
            if (!wasOpen) panel.classList.add('show');
        }

        document.addEventListener('click', (e) => {
            if (!e.target.closest('.relative')) {
                document.querySelectorAll('.dropdown-panel').forEach(p => p.classList.remove('show'));
            }
        });

        // Column toggle
        function toggleColumn(col) {
            document.querySelectorAll(`.${col}-col`).forEach(el => {
                el.style.display = el.style.display === 'none' ? '' : 'none';
            });
        }

        // Read more
        function toggleReadMore() {
            const btn = document.querySelector('.read-more');
            const extra = document.getElementById('summaryExtra');
            btn.classList.toggle('expanded');
            extra.classList.toggle('show');
        }

        // Init
        renderTable(1);
        renderPagination(1);
    </script>
</body>
